import { canonicalizePathname, matchCanonicalRoute, matchLegacyRoute } from '../routing/manifest.js'

export const SITE_URL = 'https://openacb.com'
// Generic 1200x630 link-preview card, generated by scripts/build-seo.mjs.
export const SITE_IMAGE = `${SITE_URL}/og/openacb.png`
export const SITE_IMAGE_ALT = 'openACB: estadística avanzada de la ACB y la Liga Endesa'
export const SITE_IMAGE_SIZE = Object.freeze({ width: 1200, height: 630 })
export const SITE_SCHEMA = {
  '@context': 'https://schema.org',
  '@type': 'WebSite',
  name: 'openACB',
  alternateName: 'OpenACB',
  url: `${SITE_URL}/`,
  inLanguage: 'es-ES',
}

const SITE_IMAGE_FIELDS = Object.freeze({
  image: SITE_IMAGE,
  imageAlt: SITE_IMAGE_ALT,
  imageWidth: SITE_IMAGE_SIZE.width,
  imageHeight: SITE_IMAGE_SIZE.height,
  card: 'summary_large_image',
})

export function getPageMetadata(pathname, { notFound = false } = {}) {
  const path = canonicalizePathname(pathname).toLocaleLowerCase('es')
  const canonicalMatch = matchCanonicalRoute(path)
  const route = canonicalMatch?.route || matchLegacyRoute(path)?.route
  const isMissing = notFound || !route

  return {
    title: isMissing ? 'Página no encontrada | openACB'
      : route.id === 'home' ? route.title : `${route.title} | openACB`,
    description: isMissing ? 'La dirección no corresponde a una página disponible de OpenACB.'
      : route.description,
    // UI filters share the main tool URL; entity paths remain distinct.
    // The SPA fallback must never claim that an entity page is the homepage.
    canonical: !isMissing && canonicalMatch ? `${SITE_URL}${path}` : null,
    robots: isMissing ? 'noindex, follow' : 'index, follow, max-image-preview:large',
    isHome: !isMissing && route.id === 'home',
    ...SITE_IMAGE_FIELDS,
  }
}

// [attribute, key, content] for every meta tag; null content removes the tag.
// Shared by the browser (updatePageMetadata) and the build (scripts/build-seo.mjs).
export function getMetaTags(metadata) {
  const image = metadata.image || SITE_IMAGE
  const large = (metadata.card || 'summary_large_image') === 'summary_large_image'
  return [
    ['name', 'description', metadata.description],
    ['name', 'robots', metadata.robots],
    ['property', 'og:type', 'website'],
    ['property', 'og:site_name', 'openACB'],
    ['property', 'og:locale', 'es_ES'],
    ['property', 'og:title', metadata.title],
    ['property', 'og:description', metadata.description],
    ['property', 'og:url', metadata.canonical],
    ['property', 'og:image', image],
    ['property', 'og:image:alt', metadata.imageAlt || SITE_IMAGE_ALT],
    ['property', 'og:image:width', large && metadata.imageWidth ? String(metadata.imageWidth) : null],
    ['property', 'og:image:height', large && metadata.imageHeight ? String(metadata.imageHeight) : null],
    ['name', 'twitter:card', large ? 'summary_large_image' : 'summary'],
    ['name', 'twitter:title', metadata.title],
    ['name', 'twitter:description', metadata.description],
    ['name', 'twitter:image', image],
    ['name', 'twitter:image:alt', metadata.imageAlt || SITE_IMAGE_ALT],
  ]
}

export function updatePageMetadata(metadata) {
  document.title = metadata.title

  getMetaTags(metadata).forEach(([attribute, key, content]) => {
    let element = document.head.querySelector(`meta[${attribute}="${key}"]`)
    if (content == null) {
      element?.remove()
      return
    }
    if (!element) {
      element = document.createElement('meta')
      element.setAttribute(attribute, key)
      document.head.appendChild(element)
    }
    element.content = content
  })

  let canonical = document.head.querySelector('link[rel="canonical"]')
  if (metadata.canonical) {
    if (!canonical) {
      canonical = document.createElement('link')
      canonical.rel = 'canonical'
      document.head.appendChild(canonical)
    }
    canonical.href = metadata.canonical
  } else {
    canonical?.remove()
  }

  let schema = document.getElementById('site-schema')
  if (metadata.isHome) {
    if (!schema) {
      schema = document.createElement('script')
      schema.id = 'site-schema'
      schema.type = 'application/ld+json'
      document.head.appendChild(schema)
    }
    schema.textContent = JSON.stringify(SITE_SCHEMA)
  } else {
    schema?.remove()
  }
}

// Reads the metadata the server sent with the page, so the app can keep it
// on a prerendered entity page instead of replacing it with the tool's generic one.
export function readDocumentMetadata() {
  const meta = (attribute, key) => document.head.querySelector(`meta[${attribute}="${key}"]`)?.content || null
  const width = Number(meta('property', 'og:image:width'))
  const height = Number(meta('property', 'og:image:height'))
  return {
    title: document.title,
    description: meta('name', 'description'),
    canonical: document.head.querySelector('link[rel="canonical"]')?.href || null,
    robots: meta('name', 'robots'),
    isHome: false,
    image: meta('property', 'og:image'),
    imageAlt: meta('property', 'og:image:alt'),
    imageWidth: width || null,
    imageHeight: height || null,
    card: meta('name', 'twitter:card') || 'summary_large_image',
  }
}
